-- ============================================================
-- Sistem Booking Lapangan Futsal - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:
--   mysql -u root -p < database/booking_futsal.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS booking_futsal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE booking_futsal;

DROP TABLE IF EXISTS booking;
DROP TABLE IF EXISTS lapangan;
DROP TABLE IF EXISTS pelanggan;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','kasir') NOT NULL DEFAULT 'kasir',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_usaha VARCHAR(100) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  jam_buka TINYINT NOT NULL DEFAULT 8,
  jam_tutup TINYINT NOT NULL DEFAULT 23,
  jam_malam TINYINT NOT NULL DEFAULT 17,
  min_dp_persen TINYINT NOT NULL DEFAULT 50
) ENGINE=InnoDB;

CREATE TABLE lapangan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(50) NOT NULL,
  jenis ENUM('Vinyl','Sintetis','Interlock','Parket') NOT NULL DEFAULT 'Sintetis',
  ukuran VARCHAR(30),
  harga_siang INT NOT NULL,
  harga_malam INT NOT NULL,
  status ENUM('aktif','perbaikan') NOT NULL DEFAULT 'aktif',
  keterangan VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pelanggan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  telepon VARCHAR(20) NOT NULL UNIQUE,
  nama_tim VARCHAR(100),
  member TINYINT(1) NOT NULL DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE booking (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  lapangan_id INT NOT NULL,
  pelanggan_id INT NOT NULL,
  user_id INT,
  tanggal DATE NOT NULL,
  jam_mulai TINYINT NOT NULL,
  jam_selesai TINYINT NOT NULL,
  jam_siang TINYINT NOT NULL DEFAULT 0,
  jam_malam TINYINT NOT NULL DEFAULT 0,
  total INT NOT NULL,
  dibayar INT NOT NULL DEFAULT 0,
  status ENUM('dipesan','selesai','batal') NOT NULL DEFAULT 'dipesan',
  catatan VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_jadwal (lapangan_id, tanggal),
  FOREIGN KEY (lapangan_id) REFERENCES lapangan(id),
  FOREIGN KEY (pelanggan_id) REFERENCES pelanggan(id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Password default kedua akun: admin123




-- Booking contoh: riwayat 60 hari terakhir + jadwal hari ini & besok (diisi oleh blok di bawah)

-- Kode booking berurutan sesuai tanggal
SET @n := 0;
UPDATE booking SET kode = CONCAT('BK-', LPAD(@n := @n + 1, 5, '0')) ORDER BY tanggal, jam_mulai, lapangan_id;

-- Sebagian besar booking mendatang sudah lunas (lebih realistis)
UPDATE booking SET dibayar = total WHERE status = 'dipesan' AND MOD(id, 5) < 3;
